import{_ as t,o,c as i,ak as a}from"./chunks/framework.Bs88YQSp.js";const n="data:image/png;base64,",l="/projects/Tankbot/en/latest/assets/image2.zz1-mfSe.webp",r="/projects/Tankbot/en/latest/assets/image3.Cb1oZo1M.webp",s="data:image/png;base64,",h="/projects/Tankbot/en/latest/assets/image2.zz1-mfSe.webp",c="/projects/Tankbot/en/latest/assets/image3.Ck2O8Afc.webp",p="data:image/png;base64,",g="/projects/Tankbot/en/latest/assets/image2.zz1-mfSe.webp",m="/projects/Tankbot/en/latest/assets/image3.BQkzFEYa.webp",d="/projects/Tankbot/en/latest/assets/image4.EEGCcyg9.webp",A="data:image/png;base64,",u="/projects/Tankbot/en/latest/assets/image2.BFLsINXR.webp",b="/projects/Tankbot/en/latest/assets/image2.D7_jhcwM.webp",w="/projects/Tankbot/en/latest/assets/image4.Cie1nTLz.webp",k="data:image/png;base64,",f="data:image/png;base64,",P="/projects/Tankbot/en/latest/assets/image2.zz1-mfSe.webp",x="/projects/Tankbot/en/latest/assets/image3.DNNFjt0M.webp",y="/projects/Tankbot/en/latest/assets/image2.D7_jhcwM.webp",z="/projects/Tankbot/en/latest/assets/image5.DZGImtsZ.webp",v="data:image/png;base64,",D="data:image/png;base64,",F="/projects/Tankbot/en/latest/assets/image2.CaEha6Nu.webp",N="/projects/Tankbot/en/latest/assets/image3.D5vWG1gG.webp",L="/projects/Tankbot/en/latest/assets/image4.CUDbiar4.webp",U="data:image/png;base64,",I="/projects/Tankbot/en/latest/assets/image2.DwLvr7v3.webp",C="/projects/Tankbot/en/latest/assets/image3.DQwREMKS.webp",j="/projects/Tankbot/en/latest/assets/image4.Bz8ORves.webp",T="data:image/png;base64,",V="/projects/Tankbot/en/latest/assets/image6.hj_5DQfK.webp",S="data:image/png;base64,",Q="/projects/Tankbot/en/latest/assets/image2.Cj4PsWjn.webp",E="/projects/Tankbot/en/latest/assets/image3.BDK1SYkP.webp",K="/projects/Tankbot/en/latest/assets/image4.VOYz8l9N.webp",q="/projects/Tankbot/en/latest/assets/image3.DNNFjt0M.webp",R="/projects/Tankbot/en/latest/assets/image2.D7_jhcwM.webp",Y="/projects/Tankbot/en/latest/assets/image7.sKfUAB2B.webp",Z="data:image/png;base64,",X=JSON.parse('{"title":"4.Intelligent Games Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4. Intelligent Games Lesson.md","filePath":"docs/4. Intelligent Games Lesson.md"}'),W={name:"docs/4. Intelligent Games Lesson.md"};function G(_,e,O,B,H,M){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_4-intelligent-games-lesson" tabindex="-1">4.Intelligent Games Lesson <a class="header-anchor" href="#_4-intelligent-games-lesson" aria-label="Permalink to &quot;4.Intelligent Games Lesson&quot;">​</a></h1><h2 id="_4-1-lesson-1-ultrasonic-following" tabindex="-1">4.1 Lesson 1 Ultrasonic Following <a class="header-anchor" href="#_4-1-lesson-1-ultrasonic-following" aria-label="Permalink to &quot;4.1 Lesson 1 Ultrasonic Following&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+n+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-1-1-preparation" tabindex="-1">4.1.1 Preparation <a class="header-anchor" href="#_4-1-1-preparation" aria-label="Permalink to &quot;4.1.1 Preparation&quot;">​</a></h3><ol><li>Ultrasonic sensor connection.</li></ol><img loading="lazy" height="639" width="1267" class="common_img" src="'+l+'" style="width:800px;"><ol start="2"><li>Prepare a box or a notebook.</li></ol><h3 id="_4-1-2-program-logic" tabindex="-1">4.1.2 Program logic <a class="header-anchor" href="#_4-1-2-program-logic" aria-label="Permalink to &quot;4.1.2 Program logic&quot;">​</a></h3><p>Use ultrasonic sensor to detect the distance of the obstacle ahead. And set condition to make the Tankbot move forward or backward.</p><p>Sound wave with a frequency 20~20000Hz can be heard by human, while frequency with over 20000Hz is not audible. Ultrasonic gets its name because its lower frequency limit is approximately equal to the upper limit of human hearing. Hence we call the sound wave with a frequency over 20000Hz “Ultrasonic”. Ultrasonic sensor can convert ultrasonic signal into other energy signal.</p><p>There are two probes on ultrasonic sensor, which are used to transmit and receive the ultrasonic. It will send 8 40khz square waves automatically when ranging to detect whether there is returned signal. If there is, it will output high level. The duration of high level is the time spent on transmission and returning by ultrasonic.</p><p>Formula: distance=(high level duration* sound speed(340M/S))/2</p><h3 id="_4-1-3-operation-step" tabindex="-1">4.1.3 Operation step <a class="header-anchor" href="#_4-1-3-operation-step" aria-label="Permalink to &quot;4.1.3 Operation step&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to computer through USB downloader.</p></li><li><p>Double click to open mcuisp to download</p></li><li><p>Select the corresponding port and baud rate. Then open the folder where the compiled hex file is saved, and click “Start Programming”.</p></li></ol><img loading="lazy" height="592" width="645" class="common_img" src="'+r+'" style="width:800px;"><ol start="5"><li>Please wait till the program is burned. After that, reinsert the jumper cap into the STM32, and then press RST button.</li></ol><h3 id="_4-1-4-function-realization" tabindex="-1">4.1.4 Function Realization <a class="header-anchor" href="#_4-1-4-function-realization" aria-label="Permalink to &quot;4.1.4 Function Realization&quot;">​</a></h3><p>Place the Tankbot on the flat ground. Place a box or book in front of the ultrasonic sensor, then it will range the distance between them. When move the book towards ultrasonic sensor, Tankbot will move backwards. When move the book backward, it will move forward.</p><h2 id="_4-2-lesson-2-ultrasonic-obstacle-avoidance" tabindex="-1">4.2 Lesson 2 Ultrasonic Obstacle Avoidance <a class="header-anchor" href="#_4-2-lesson-2-ultrasonic-obstacle-avoidance" aria-label="Permalink to &quot;4.2 Lesson 2 Ultrasonic Obstacle Avoidance&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+s+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-2-1-preparation" tabindex="-1">4.2.1 Preparation <a class="header-anchor" href="#_4-2-1-preparation" aria-label="Permalink to &quot;4.2.1 Preparation&quot;">​</a></h3><ol><li>Ultrasonic sensor connection.</li></ol><img loading="lazy" height="639" width="1267" class="common_img" src="'+h+'" style="width:800px;"><ol start="2"><li>Prepare a few boxes</li></ol><h3 id="_4-2-2-program-logic" tabindex="-1">4.2.2 Program logic <a class="header-anchor" href="#_4-2-2-program-logic" aria-label="Permalink to &quot;4.2.2 Program logic&quot;">​</a></h3><p>Use the ultrasonic sensor to detect the distance of the obstacle ahead, and make Tankbot avoid the obstacle automatically through programming.</p><p>Sound wave with a frequency 20~20000Hz can be heard by human, while frequency with over 20000Hz is not audible. Ultrasonic gets its name because its lower frequency limit is approximately equal to the upper limit of human hearing. Hence we call the sound wave with a frequency over 20000Hz “Ultrasonic”. Ultrasonic sensor can convert ultrasonic signal into other energy signal, electrical signals generally.</p><p>There are two probes on ultrasonic sensor, which are used to transmit and receive the ultrasonic. It will send 8 40khz square waves automatically when ranging to detect whether there is returned signal. If there is, it will output high level. The duration of high level is the time spent on transmission and returning by ultrasonic.</p><p>Formula: distance=(high level duration* sound speed(340M/S))/2</p><h3 id="_4-2-3-operation-steps" tabindex="-1">4.2.3 Operation steps <a class="header-anchor" href="#_4-2-3-operation-steps" aria-label="Permalink to &quot;4.2.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32</p></li><li><p>Connect the controller to computer through USB, and then switch on the controller.</p></li><li><p>Double click to open mcuisp downloader.</p></li><li><p>Select the corresponding port and baud rate. Then open the folder where the compiled hex file is saved, and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="648" class="common_img" src="'+c+'" style="width:800px;"><ol start="5"><li>Please wait till the program is burned. After that, reinsert the jumper cap into the STM32, and then press RST button.</li></ol><h3 id="_4-2-4-function-realization" tabindex="-1">4.2.4 Function realization <a class="header-anchor" href="#_4-2-4-function-realization" aria-label="Permalink to &quot;4.2.4 Function realization&quot;">​</a></h3><p>Build obstacle avoidance environment with some boxes. When Tankbot is moving forward, it will detect whether there is box ahead through ultrasonic sensor. If there is, it will make a turn and continue its moving.</p><h2 id="_4-3-lesson-3-fixed-distance-picking" tabindex="-1">4.3 Lesson 3 Fixed Distance Picking <a class="header-anchor" href="#_4-3-lesson-3-fixed-distance-picking" aria-label="Permalink to &quot;4.3 Lesson 3 Fixed Distance Picking&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+p+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-3-1-preparation" tabindex="-1">4.3.1 Preparation <a class="header-anchor" href="#_4-3-1-preparation" aria-label="Permalink to &quot;4.3.1 Preparation&quot;">​</a></h3><ol><li>Ultrasonic sensor connection.</li></ol><img loading="lazy" height="639" width="1267" class="common_img" src="'+g+'" style="width:800px;"><ol start="2"><li>Robotic arm installed on the tank.</li></ol><img loading="lazy" height="808" width="808" class="common_img" src="'+m+'" style="width:800px;"><ol start="3"><li>Prepare an object to pick. Its weight should not be over 200g, its height should be greater than 20cm and its width is around 3cm.</li></ol><h3 id="_4-3-2-program-logic" tabindex="-1">4.3.2 Program logic <a class="header-anchor" href="#_4-3-2-program-logic" aria-label="Permalink to &quot;4.3.2 Program logic&quot;">​</a></h3><p>Picking function is realized by the combination of ultrasonic sensor and servos. Firstly, range the distance between the object and Tankbot through the ultrasonic sensor. When the distance meets the set value, the servos on the robotic arm will execute the picking action.</p><h3 id="_4-3-3-operation-steps" tabindex="-1">4.3.3 Operation steps <a class="header-anchor" href="#_4-3-3-operation-steps" aria-label="Permalink to &quot;4.3.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to computer through USB.</p></li><li><p>Double click to open mcuisp</p></li><li><p>Select the corresponding port and baud rate. Then open the folder where the compiled hex file is saved, and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="648" class="common_img" src="'+d+'" style="width:800px;"><ol start="5"><li>Please wait till the program is burned. After that, reinsert the jumper cap into the STM32, and then press RST button.</li></ol><h3 id="_4-3-4-function-realization" tabindex="-1">4.3.4 Function Realization <a class="header-anchor" href="#_4-3-4-function-realization" aria-label="Permalink to &quot;4.3.4 Function Realization&quot;">​</a></h3><p>Place the object in front of the ultrasonic sensor. After the ultrasonic sensor detects the object, the robotic arm will pick the object and place it aside.</p><h2 id="_4-4-lesson-4-line-following" tabindex="-1">4.4 Lesson 4 Line Following <a class="header-anchor" href="#_4-4-lesson-4-line-following" aria-label="Permalink to &quot;4.4 Lesson 4 Line Following&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+A+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-4-1-preparation" tabindex="-1">4.4.1 Preparation <a class="header-anchor" href="#_4-4-1-preparation" aria-label="Permalink to &quot;4.4.1 Preparation&quot;">​</a></h3><ol><li><p>4-channel line follower connection</p></li><li><p><img loading="lazy" height="779" width="1537" class="common_img" src="'+u+'" style="width:800px;">Prepare black line and it should not be too thick.</p></li></ol><img loading="lazy" height="559" width="559" class="common_img" src="'+b+'" style="width:800px;"><h3 id="_4-4-2-program-logic" tabindex="-1">4.4.2 Program logic <a class="header-anchor" href="#_4-4-2-program-logic" aria-label="Permalink to &quot;4.4.2 Program logic&quot;">​</a></h3><p>This game is by 4-channel line follower. And there are four probes on it. Each probe involves a pair of infrared receiver and infrared receiver.</p><p>Because the light can be reflected, the reflected light will be formed when the light emitted by infrared encounters an object. If the infrared light is reflected, when it encounters a white or other light-colored surface, the receiver will receive an infrared signal. At this time, the blue LED indicator in the back of the line follower will be on. If the infrared light is absorbed or cannot be reflected, the receiver cannot receive the infrared signal.</p><p>When the receiver probe receives the signal, it will send the signal to the microcontroller. Finally, the internal program in microcontroller will control the Tankbot’s movement.</p><h3 id="_4-4-3-operation-steps" tabindex="-1">4.4.3 Operation steps <a class="header-anchor" href="#_4-4-3-operation-steps" aria-label="Permalink to &quot;4.4.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to computer through USB downloader.</p></li><li><p>Double click to open mcuisp.</p></li><li><p>Select the corresponding port and baud rate. Then open the folder where the compiled hex file is saved, and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="648" class="common_img" src="'+w+'" style="width:800px;"><ol start="5"><li>Please wait till the program is burned. After that, reinsert the jumper cap into the STM32, and then press RST button.</li></ol><h3 id="_4-4-4-function-realization" tabindex="-1">4.4.4 Function realization <a class="header-anchor" href="#_4-4-4-function-realization" aria-label="Permalink to &quot;4.4.4 Function realization&quot;">​</a></h3><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+k+'" style="width:30px;">If its line following performance doesn’t meet your requirement, you can adjust its sensitivity. For more details, you can refer to the demo video “Line Follower Sensitivity Adjustment” in “Appendix-&gt;4.Debugging Tutorial”.</p><p>Place Tankbot on the laid black line, and then the Tankbot will move along the black line.</p><h2 id="_4-5-lesson-5-line-following-and-picking" tabindex="-1">4.5 Lesson 5 Line Following and Picking <a class="header-anchor" href="#_4-5-lesson-5-line-following-and-picking" aria-label="Permalink to &quot;4.5 Lesson 5 Line Following and Picking&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+f+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-5-1-preparation" tabindex="-1">4.5.1 Preparation <a class="header-anchor" href="#_4-5-1-preparation" aria-label="Permalink to &quot;4.5.1 Preparation&quot;">​</a></h3><ol><li>Ultrasonic connection</li></ol><img loading="lazy" height="639" width="1267" class="common_img" src="'+P+'" style="width:800px;"><ol start="2"><li>4-channel line follower connection.</li></ol><img loading="lazy" height="684" width="1349" class="common_img" src="'+x+'" style="width:800px;"><ol start="3"><li>Prepare a black line which should not be too thick.</li></ol><img loading="lazy" height="559" width="559" class="common_img" src="'+y+'" style="width:800px;"><ol start="4"><li>Prepare an object to pick, whose weight should not exceed 200g, height should be greater than 20cm, and width should be approximately equal to 3cm.</li></ol><h3 id="_4-5-2-program-logic" tabindex="-1">4.5.2 Program logic <a class="header-anchor" href="#_4-5-2-program-logic" aria-label="Permalink to &quot;4.5.2 Program logic&quot;">​</a></h3><p>This game is the combination of games “<strong>Fixed Distance Picking</strong>” and “<strong>Line Following</strong>”. Firstly, use 4-channel line follower to detect the black line to make Tankbot move along the black line. Next, the ultrasonic sensor will be used for obstacle detection. If the obstacle is within the detection range, the robotic arm will pick the obstacle after detection.</p><h3 id="_4-5-3-operation-steps" tabindex="-1">4.5.3 Operation steps <a class="header-anchor" href="#_4-5-3-operation-steps" aria-label="Permalink to &quot;4.5.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to the computer through USB, and then switch on the controller.</p></li><li><p>Double click to open mcuisp.</p></li><li><p>Select the corresponding port and baud rate. Then, open the compiled hex file and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="647" class="common_img" src="'+z+'" style="width:800px;"><ol start="5"><li>Wail for the program to burn. After the program is burned, reinsert the jumper cap into STM32, and press RST button.</li></ol><h3 id="_4-5-4-function-realization" tabindex="-1">4.5.4 Function realization <a class="header-anchor" href="#_4-5-4-function-realization" aria-label="Permalink to &quot;4.5.4 Function realization&quot;">​</a></h3><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+v+'" style="width:30px;">If the line following performance cannot meet your requirement, you can adjust the sensitivity of the sensor according to the video in “7.Appendix-&gt;4.Debugging Tutorial”.</p><p>Place an object on the laid black line. Tankbot will move along the black line. Having detected the object ahead through ultrasonic sensor, it will place the object aside and move on.</p><h2 id="_4-6-lesson-6-standing-after-rollover" tabindex="-1">4.6 Lesson 6 Standing after Rollover <a class="header-anchor" href="#_4-6-lesson-6-standing-after-rollover" aria-label="Permalink to &quot;4.6 Lesson 6 Standing after Rollover&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+D+'" style="width:30px;">The demo video is in this folder for reference.</p><h3 id="_4-6-1-preparation" tabindex="-1">4.6.1 Preparation <a class="header-anchor" href="#_4-6-1-preparation" aria-label="Permalink to &quot;4.6.1 Preparation&quot;">​</a></h3><ol><li>acceleration sensor connection.</li></ol><img loading="lazy" height="751" width="1248" class="common_img" src="'+F+'" style="width:800px;"><ol start="2"><li>The robotic arm installed on the tank.</li></ol><img loading="lazy" height="719" width="719" class="common_img" src="'+N+'" style="width:800px;"><h3 id="_4-6-2-program-logic" tabindex="-1">4.6.2 Program logic <a class="header-anchor" href="#_4-6-2-program-logic" aria-label="Permalink to &quot;4.6.2 Program logic&quot;">​</a></h3><p>Detect the current state of the Tankbot through acceleration sensor. Based on the robot state, run the built-in action group to make the robot “stand” after rollover.</p><p>Acceleration sensor is composed of accelerometer and gyroscope. Accelerometer can measure linear acceleration, and the gyroscope measures angular velocity</p><p>Accelerometer is based on the force balance principle and gyroscope is based on inertia principle. The value measured by accelerometer over a long period of time is accurate, while there will be error in the value measured in a short period of time due to the noise. However, gyroscope takes the opposite. Therefore, the cooperation of these two is needed to achieve the correct navigation.</p><h3 id="_4-6-3-operation-steps" tabindex="-1">4.6.3 Operation steps <a class="header-anchor" href="#_4-6-3-operation-steps" aria-label="Permalink to &quot;4.6.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to the computer through USB, and then switch on the controller.</p></li><li><p>Double click to open mcuisp.</p></li><li><p>Select the corresponding port and baud rate. Then, open the compiled hex file and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="647" class="common_img" src="'+L+'" style="width:800px;"><ol start="5"><li>Wail for the program to burn. After the program is burned, reinsert the jumper cap into STM32, and press RST button.</li></ol><h3 id="_4-6-4-function-realization" tabindex="-1">4.6.4 Function realization <a class="header-anchor" href="#_4-6-4-function-realization" aria-label="Permalink to &quot;4.6.4 Function realization&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Please place the Tankbot on hard ground.</p></div><p>Place the Tankbot side on flat ground. After a while, the Tankbot will “stand” after rollover.</p><h2 id="_4-7-lesson-7-sound-control" tabindex="-1">4.7 Lesson 7 Sound Control <a class="header-anchor" href="#_4-7-lesson-7-sound-control" aria-label="Permalink to &quot;4.7 Lesson 7 Sound Control&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+U+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-7-1-preparation" tabindex="-1">4.7.1 Preparation <a class="header-anchor" href="#_4-7-1-preparation" aria-label="Permalink to &quot;4.7.1 Preparation&quot;">​</a></h3><ol><li>sound sensor connection</li></ol><img loading="lazy" height="735" width="1267" class="common_img" src="'+I+'" style="width:800px;"><ol start="2"><li>The robotic arm installed on the tank.</li></ol><img loading="lazy" height="739" width="738" class="common_img" src="'+C+'" style="width:800px;"><ol start="3"><li>Prepare an object to pick, whose weight should not exceed 200g.</li></ol><h3 id="_4-7-2-program-logic" tabindex="-1">4.7.2 Program logic <a class="header-anchor" href="#_4-7-2-program-logic" aria-label="Permalink to &quot;4.7.2 Program logic&quot;">​</a></h3><p>The sound sensor is equivalent to a switch and detects sound intensity through the ADC output. The detection range is from 0 to 1023. The greater the sound intensity is, the greater the value will be. Therefore, we can control the robotic arm to pick objects by obtaining the sound value.</p><h3 id="_4-7-3-operation-steps" tabindex="-1">4.7.3 Operation steps <a class="header-anchor" href="#_4-7-3-operation-steps" aria-label="Permalink to &quot;4.7.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to the computer through USB, and then switch on the controller.</p></li><li><p>Double click to open mcuisp.</p></li><li><p>Select the corresponding port and baud rate. Then, open the compiled hex file and click “Start Programming”.</p></li></ol><img loading="lazy" height="441" width="687" class="common_img" src="'+j+'" style="width:800px;"><ol start="5"><li>Wail for the program to burn. After the program is burned, reinsert the jumper cap into STM32, and press RST button.</li></ol><h3 id="_4-7-4-function-realization" tabindex="-1">4.7.4 Function realization <a class="header-anchor" href="#_4-7-4-function-realization" aria-label="Permalink to &quot;4.7.4 Function realization&quot;">​</a></h3><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+T+'" style="width:30px;">Please play this game in quiet environment.</p><p>Face the Tankbot and place the object to the right side. Then clap to make a sound. When the clap is first detected by the sound sensor, the indicator on it will light up and the robotic arm will pick and place the object to the right side of Tankbot. When the second sound is sensed, the robotic arm will pick and place the object at the right side to the other side. And Tankbot will execute alternately in this direction.</p><img loading="lazy" height="906" width="1267" class="common_img" src="'+V+'" style="width:800px;"><h2 id="_4-8-lesson-8-games-switching" tabindex="-1">4.8 Lesson 8 Games Switching <a class="header-anchor" href="#_4-8-lesson-8-games-switching" aria-label="Permalink to &quot;4.8 Lesson 8 Games Switching&quot;">​</a></h2><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+S+'" style="width:30px;">The demo video is in this folder for your reference.</p><h3 id="_4-8-1-preparation" tabindex="-1">4.8.1 Preparation <a class="header-anchor" href="#_4-8-1-preparation" aria-label="Permalink to &quot;4.8.1 Preparation&quot;">​</a></h3><ol><li>handle receiver connection.</li></ol><img loading="lazy" height="700" width="593" class="common_img" src="'+Q+'" style="width:800px;"><ol start="2"><li>Bluetooth module connection.</li></ol><img loading="lazy" height="585" width="515" class="common_img" src="'+E+'" style="width:800px;"><ol start="3"><li>acceleration sensor connection.</li></ol><img loading="lazy" height="762" width="1266" class="common_img" src="'+K+'" style="width:800px;"><ol start="4"><li>4-channel line follower connection.</li></ol><img loading="lazy" height="684" width="1349" class="common_img" src="'+q+'" style="width:800px;"><ol start="5"><li>Prepare a black line which should not be too thick.</li></ol><img loading="lazy" height="559" width="559" class="common_img" src="'+R+'" style="width:800px;"><h3 id="_4-8-2-program-logic" tabindex="-1">4.8.2 Program logic <a class="header-anchor" href="#_4-8-2-program-logic" aria-label="Permalink to &quot;4.8.2 Program logic&quot;">​</a></h3><p>This game is a combination of four different games. By pressing the function key on the controller, you can switch between four games, including handle control, phone control, line following and standing after rollover.</p><h3 id="_4-8-3-operation-steps" tabindex="-1">4.8.3 Operation steps <a class="header-anchor" href="#_4-8-3-operation-steps" aria-label="Permalink to &quot;4.8.3 Operation steps&quot;">​</a></h3><ol><li><p>Remove the jumper cap on STM32.</p></li><li><p>Connect the controller to the computer through USB downloader, and then switch on the controller.</p></li><li><p>Double click to open mcuisp downloader.</p></li><li><p>Select the corresponding port and baud rate. Then, open the compiled hex file and click “Start Programming”.</p></li></ol><img loading="lazy" height="585" width="648" class="common_img" src="'+Y+'" style="width:800px;"><ol start="5"><li>Wail for the program to burn. After the program is burned, reinsert the jumper cap into STM32, and press RST button.</li></ol><h3 id="_4-8-4-function-realization" tabindex="-1">4.8.4 Function realization <a class="header-anchor" href="#_4-8-4-function-realization" aria-label="Permalink to &quot;4.8.4 Function realization&quot;">​</a></h3><p><img loading="lazy" height="44" width="44" class="inline-icon" src="'+Z+'" style="width:30px;">Please pay attention you cannot control the Tankbot through phone and handle simultaneously. If you fail to switch the game, you can press the function key for several times till the blue signal flashes, which means that the game is switched successfully.</p><p>When the program is executed, the Tankbot is in handle and phone control mode by default, and you can directly experience handle or phone control.</p><ol><li><p>Press the function key, and then the blue signal will flash once, which means that the game is switched to line following.</p></li><li><p>Press the function key again, and then the blue signal will flash once, indicating that the game is switched to standing after rollover.</p></li><li><p>Press the function key again, and then the blue signal will flash once meaning that the game is switched to phone and handle control.</p></li></ol>',145)])])}const $=t(W,[["render",G]]);export{X as __pageData,$ as default};
